mapper.sql:
FROM fbs_inventory fi WHERE fi.is_deleted = FALSE
AND ${params.sqlMap.default}
${params.permissionSql}
AND NOT ( fi.recommended_replenishment_qty = 0 AND fi.total_stock_qty = 0 AND fi.stocked_inbound_qty = 0 AND fi.transfer_asn_inbound_qty = 0 AND fi.reserved_qty = 0 AND fi.unsellable_qty = 0 AND fi.in_transit_qty = 0 )
